import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`career-coach-audit`,heroTitle:`Audit any career coach in minutes`,heroSubtitle:`Perplexity Computer reviews a career coach website, proof, specialty, and funnel, then turns the signals into a clear hiring recommendation.`,inputUrlCta:`Audit this coach`,inputUrlPlaceholder:`coachsite.com`,inputUrlPrefill:`Go to {url} and run a full career coach audit. 1) Review the coach website, target roles, service packages, testimonials, credentials, and booking flow. 2) Check whether the coach has credible proof for the specific career outcome they promise. 3) Benchmark comparable career coaches or programs where useful. 4) Identify red flags, missing evidence, vague claims, and questions the buyer should ask before paying. 5) Deliver a concise audit with a fit score, strongest and weakest signals, recommended questions, and next steps.`,heroOverlaySteps:[`Reviewing specialty, service packages, testimonials, and booking flow`,`Checking proof against the specific career outcome being promised`,`Benchmarking comparable career coaches and programs`,`Fit score, red flags, and questions to ask ready to use`],generatingSteps:[`Visiting {url} to review the coach site, packages, and proof signals`,`Designing an agent to benchmark comparable coaches and career programs`,`Configuring checks for vague claims, missing evidence, and buyer risks`,`Preparing a career-coach audit with fit score and follow-up questions`],featureSectionTitle:`From sales page to confident coaching decision`,featureCardTitles:[`Connects to your career research`,`Outputs you can use before buying`],featureCardDescriptions:[`Computer breaks the audit into specialty fit, proof review, funnel analysis, and market benchmarking so the decision is based on evidence.`,`Docs, Sheets, notes, and job-search materials can stay connected while Computer compares the coach against your actual career goals.`,`Fit score. Red flags. Proof summary. Questions to ask before booking. Computer gives you a practical view of whether the coach is credible.`],capabilitySectionTitle:`Your career-coach due-diligence analyst, on demand`,capabilitySectionSubtitle:`Paste a coach URL, step away, and come back to a clearer view of the offer.`,capabilityCards:[{title:`Specialty Fit Review`,description:`Computer can inspect target roles, industries, seniority, and package details to see whether the coach matches your goals.`},{title:`Proof Analysis`,description:`Computer can evaluate testimonials, outcomes, credentials, and case studies to separate credible results from generic marketing.`},{title:`Buyer Risk Checks`,description:`Computer can flag vague claims, missing pricing context, weak guarantees, and unclear deliverables before you book a call.`},{title:`Connect Your Tools`,description:`Computer can organize findings across docs, sheets, and job-search notes so comparisons stay easy to review.`},{title:`Remember Your Goals`,description:`Computer can remember your target roles, constraints, and coaching criteria so future audits reflect what you actually need.`},{title:`Compare Shortlists`,description:`Computer can audit multiple coaches over time and maintain a ranked view of proof, fit, cost signals, and next steps.`}]});export{t as default};
